def tidy_existing_jobs(apps, schema_editor):
    """Give jobs already in the database short titles, and hide parts orders and repeats."""
    from contracts.cleanup import dupe_key, is_goods, short_title
    from contracts.importer import mark_repeats

    Contract = apps.get_model("contracts", "Contract")
    batch = []
    for c in Contract.objects.select_related("agency").iterator(chunk_size=1000):
        c.short_title = short_title(c.title)[:120]
        c.is_goods = is_goods(c.psc_code, c.title)
        c.dupe_key = dupe_key(c.solicitation_number, c.agency.name if c.agency else "", c.title,
                              c.agency.office if c.agency else "", c.due_date)
        batch.append(c)
        if len(batch) == 1000:
            Contract.objects.bulk_update(batch, ["short_title", "is_goods", "dupe_key"])
            batch = []
    Contract.objects.bulk_update(batch, ["short_title", "is_goods", "dupe_key"])
    mark_repeats(Contract)


